  '値段も|味も|よい|安ければ': { order: [1, 4, 2, 3], starSlot: 2, starChoice: 4, translation: 'At that restaurant, the prices are cheap and the food is delicious, but the trouble is that it is always crowded.' },
  '新しい|新社長|として|体制': { order: [2, 3, 1, 4], starSlot: 2, starChoice: 3, translation: 'With the former president\'s son as the new president, we will launch a new organizational structure.' },
